step.code_example:
export type OnboardingFormType = 'quick' | 'complex'
export interface OnboardingMeta { version: number createdAt: string updatedAt: string completionLevel: 'quick_start' | 'partial' | 'complete' formType?: OnboardingFormType // Optional for backwards compatibility }
export interface Onboarding { workspaceId: string goal: Goal audience: Audience voice: Voice contentStrategy: ContentStrategy constraints: Constraints sales: Sales examples?: Examples additionalInfo?: string meta: OnboardingMeta }
export interface Workspace { id: string userId: string name: string description: string | null avatarUrl: string | null isDefault: boolean onboarding: Onboarding | null createdAt: string updatedAt: string }


/**
 * Gets the form type for a workspace with fallback for legacy workspaces.
 *
 * @param onboarding - The workspace onboarding data
 * @returns 'quick' or 'complex'
 */
export function getWorkspaceFormType(onboarding: Onboarding | null): OnboardingFormType {
  if (!onboarding?.meta) {
    return 'quick' // Default fallback
  }

  // Use explicit formType if available
  if (onboarding.meta.formType) {
    return onboarding.meta.formType
  }

  // Fallback: derive from completionLevel for legacy workspaces
  return onboarding.meta.completionLevel === 'quick_start' ? 'quick' : 'complex'
}

/**
 * Checks if a workspace is using the quick form
 */
export function isQuickForm(workspace: Workspace): boolean {
  return getWorkspaceFormType(workspace.onboarding) === 'quick'
}

/**
 * Checks if a workspace is using the complex form
 */
export function isComplexForm(workspace: Workspace): boolean {
  return getWorkspaceFormType(workspace.onboarding) === 'complex'
}


// In Quick Start form submission
const handleQuickStartSubmit = async (data: QuickStartFormData) => {
  const payload = {
    name: workspaceName,
    onboarding: {
      formType: 'quick' as const,  // Explicitly mark as quick form
      goal: { primaryGoal: data.goal },
      audience: { audienceType: data.audience },
      voice: { tones: data.tones },
      contentStrategy: { pillars: data.pillars },
      constraints: { platforms: data.platforms }
    }
  }

  await createWorkspace(payload)
}

// In Complex form submission
const handleComplexSubmit = async (data: ComplexFormData) => {
  const payload = {
    name: workspaceName,
    onboarding: {
      formType: 'complex' as const,  // Explicitly mark as complex form
      goal: {
        primaryGoal: data.goal.primaryGoal,
        expectedOutcome: data.goal.expectedOutcome,
        successSignals: data.goal.successSignals
      },
      audience: {
        audienceType: data.audience.audienceType,
        awarenessLevel: data.audience.awarenessLevel,
        painOrDesire: data.audience.painOrDesire,
        languages: data.audience.languages
      },
      // ... all other fields
    }
  }

  await createWorkspace(payload)
}


import { useState, useEffect } from 'react'
import { getWorkspaceFormType } from '@/utils/workspace'
import QuickOnboardingForm from './QuickOnboardingForm'
import ComplexOnboardingForm from './ComplexOnboardingForm'

interface EditWorkspaceOnboardingProps {
  workspace: Workspace
  onSave: (data: OnboardingUpdatePayload) => Promise<void>
}

export function EditWorkspaceOnboarding({ workspace, onSave }: EditWorkspaceOnboardingProps) {
  // Determine which form to show based on formType
  const initialFormType = getWorkspaceFormType(workspace.onboarding)
  const [currentFormType, setCurrentFormType] = useState<OnboardingFormType>(initialFormType)

  // Track if user has switched forms
  const [hasChangedFormType, setHasChangedFormType] = useState(false)

  const handleFormTypeSwitch = (newFormType: OnboardingFormType) => {
    setCurrentFormType(newFormType)
    setHasChangedFormType(true)
  }

  const handleSave = async (data: Partial<Onboarding>) => {
    const payload = {
      ...data,
      // Include formType if user switched forms
      ...(hasChangedFormType && { formType: currentFormType })
    }

    await onSave(payload)
  }

  return (
    <div className="edit-workspace-onboarding">
      {/* Form Type Selector (optional - allow switching) */}
      <FormTypeToggle
        currentType={currentFormType}
        onSwitch={handleFormTypeSwitch}
      />

      {/* Show appropriate form based on current form type */}
      {currentFormType === 'quick' ? (
        <QuickOnboardingForm
          initialData={workspace.onboarding}
          onSubmit={handleSave}
        />
      ) : (
        <ComplexOnboardingForm
          initialData={workspace.onboarding}
          onSubmit={handleSave}
        />
      )}
    </div>
  )
}


export interface UpdateOnboardingPayload {
  goal?: Partial<Goal>
  audience?: Partial<Audience>
  voice?: Partial<Voice>
  contentStrategy?: Partial<ContentStrategy>
  constraints?: Partial<Constraints>
  sales?: Partial<Sales>
  examples?: Examples
  additionalInfo?: string
  formType?: OnboardingFormType  // Include when switching forms
}

export async function updateWorkspaceOnboarding(
  workspaceId: string,
  data: UpdateOnboardingPayload
): Promise<Onboarding> {
  const response = await fetch(`/api/workspaces/${workspaceId}/onboarding`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data)
  })

  if (!response.ok) {
    throw new Error('Failed to update onboarding')
  }

  return response.json()
}


const handleSwitchToQuick = () => {
  // Check if complex fields have data
  const hasComplexData = checkForComplexData(workspace.onboarding)

  if (hasComplexData) {
    // Show confirmation dialog
    showConfirmDialog({
      title: 'Switch to Quick Start Form?',
      message: 'You have additional details filled in. Switching to Quick Start will hide these fields (they won\'t be deleted, just hidden). Continue?',
      confirmLabel: 'Switch to Quick',
      onConfirm: () => {
        setCurrentFormType('quick')
        setHasChangedFormType(true)
      }
    })
  } else {
    // No data loss, switch immediately
    setCurrentFormType('quick')
    setHasChangedFormType(true)
  }
}

function checkForComplexData(onboarding: Onboarding | null): boolean {
  if (!onboarding) return false

  // Check if any "complex-only" fields have values
  return !!(
    onboarding.goal?.expectedOutcome ||
    onboarding.goal?.successSignals?.length ||
    onboarding.audience?.awarenessLevel ||
    onboarding.audience?.painOrDesire ||
    onboarding.voice?.brandType ||
    onboarding.voice?.perspective ||
    onboarding.contentStrategy?.topics?.length ||
    onboarding.contentStrategy?.formats?.length ||
    onboarding.contentStrategy?.postingFrequency ||
    onboarding.constraints?.hardConstraints?.length ||
    onboarding.examples?.likedPost ||
    onboarding.examples?.dislikedPost ||
    onboarding.additionalInfo
  )
}

example.code:

import { useState } from 'react'
import { useWorkspace } from '@/hooks/useWorkspace'
import { getWorkspaceFormType, isQuickForm } from '@/utils/workspace'
import { updateWorkspaceOnboarding } from '@/api/workspaces'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { AlertDialog } from '@/components/ui/alert-dialog'
import QuickOnboardingForm from './QuickOnboardingForm'
import ComplexOnboardingForm from './ComplexOnboardingForm'

interface EditWorkspaceOnboardingProps {
  workspaceId: string
}

export function EditWorkspaceOnboarding({ workspaceId }: EditWorkspaceOnboardingProps) {
  const { workspace, loading, refetch } = useWorkspace(workspaceId)

  // Determine initial form type from workspace data
  const initialFormType = workspace ? getWorkspaceFormType(workspace.onboarding) : 'quick'

  const [currentFormType, setCurrentFormType] = useState<OnboardingFormType>(initialFormType)
  const [hasChangedFormType, setHasChangedFormType] = useState(false)
  const [isSaving, setIsSaving] = useState(false)
  const [showSwitchDialog, setShowSwitchDialog] = useState(false)
  const [pendingFormType, setPendingFormType] = useState<OnboardingFormType | null>(null)

  if (loading || !workspace) {
    return <div>Loading...</div>
  }

  const handleFormTypeSwitch = (newFormType: OnboardingFormType) => {
    // If switching from complex to quick and complex data exists, show warning
    if (newFormType === 'quick' && currentFormType === 'complex') {
      const hasComplexData = checkForComplexData(workspace.onboarding)
      if (hasComplexData) {
        setPendingFormType(newFormType)
        setShowSwitchDialog(true)
        return
      }
    }

    // Switch immediately
    performFormTypeSwitch(newFormType)
  }

  const performFormTypeSwitch = (newFormType: OnboardingFormType) => {
    setCurrentFormType(newFormType)
    setHasChangedFormType(true)
    setShowSwitchDialog(false)
    setPendingFormType(null)
  }

  const handleSave = async (data: Partial<Onboarding>) => {
    setIsSaving(true)

    try {
      const payload = {
        ...data,
        // Only include formType if user switched forms
        ...(hasChangedFormType && { formType: currentFormType })
      }

      await updateWorkspaceOnboarding(workspaceId, payload)
      await refetch()

      // Reset changed flag after successful save
      setHasChangedFormType(false)

      // Show success message
      showToast({ message: 'Workspace updated successfully', type: 'success' })
    } catch (error) {
      showToast({ message: 'Failed to update workspace', type: 'error' })
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <div className="edit-workspace-onboarding max-w-4xl mx-auto p-6">
      {/* Header with form type indicator */}
      <div className="mb-8">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-2xl font-bold">Edit Workspace Onboarding</h1>
          <Badge variant={currentFormType === 'quick' ? 'default' : 'secondary'}>
            {currentFormType === 'quick' ? 'Quick Start' : 'Complete Setup'}
          </Badge>
        </div>

        {/* Form type toggle */}
        <div className="bg-slate-50 rounded-lg p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-slate-900 mb-1">
                {currentFormType === 'quick' ? 'Quick Start Mode' : 'Complete Setup Mode'}
              </p>
              <p className="text-xs text-slate-600">
                {currentFormType === 'quick'
                  ? 'Editing essential fields only. Switch to Complete Setup for full customization.'
                  : 'Editing all available fields for maximum personalization.'
                }
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleFormTypeSwitch(currentFormType === 'quick' ? 'complex' : 'quick')}
            >
              Switch to {currentFormType === 'quick' ? 'Complete' : 'Quick'}
            </Button>
          </div>
        </div>
      </div>

      {/* Form */}
      {currentFormType === 'quick' ? (
        <QuickOnboardingForm
          initialData={workspace.onboarding}
          onSubmit={handleSave}
          isLoading={isSaving}
        />
      ) : (
        <ComplexOnboardingForm
          initialData={workspace.onboarding}
          onSubmit={handleSave}
          isLoading={isSaving}
        />
      )}

      {/* Switch confirmation dialog */}
      <AlertDialog
        open={showSwitchDialog}
        onOpenChange={setShowSwitchDialog}
      >
        <AlertDialog.Content>
          <AlertDialog.Header>
            <AlertDialog.Title>Switch to Quick Start Form?</AlertDialog.Title>
            <AlertDialog.Description>
              You have additional details filled in. Switching to Quick Start will hide these fields
              (they won't be deleted, just hidden). You can switch back to Complete Setup anytime to see them again.
            </AlertDialog.Description>
          </AlertDialog.Header>
          <AlertDialog.Footer>
            <AlertDialog.Cancel onClick={() => setShowSwitchDialog(false)}>
              Cancel
            </AlertDialog.Cancel>
            <AlertDialog.Action onClick={() => performFormTypeSwitch(pendingFormType!)}>
              Switch to Quick Start
            </AlertDialog.Action>
          </AlertDialog.Footer>
        </AlertDialog.Content>
      </AlertDialog>
    </div>
  )
}

function checkForComplexData(onboarding: Onboarding | null): boolean {
  if (!onboarding) return false

  return !!(
    onboarding.goal?.expectedOutcome ||
    onboarding.goal?.successSignals?.length ||
    onboarding.audience?.awarenessLevel ||
    onboarding.audience?.painOrDesire ||
    onboarding.voice?.brandType ||
    onboarding.voice?.perspective ||
    onboarding.contentStrategy?.topics?.length ||
    onboarding.contentStrategy?.formats?.length ||
    onboarding.contentStrategy?.postingFrequency ||
    onboarding.constraints?.hardConstraints?.length ||
    onboarding.examples?.likedPost ||
    onboarding.examples?.dislikedPost ||
    onboarding.additionalInfo
  )
}
